\label{thm:recip}
		For every $\varepsilon>0$, uniformly for this family,
		\begin{equation}\label{eq:recipmain}
			|S|\lesssim_\varepsilon HT^{\beta+\varepsilon},\qquad
			1\le H\le MT^{-\beta},\quad M\le T^{1/2}.
		\end{equation}

\label{prop:preliminary}
		For the reciprocal sum \eqref{eq:S}, uniformly on subintervals,
		\begin{equation}\label{eq:preliminary}
			|S|/H\lesssim (HT)^{2/7}+\frac{M^2}{HT},\qquad
			|S|/H\lesssim \rho^{13/31}M^{3/31}+\frac{M^2}{HT}.
		\end{equation}
		Consequently $|S|/H\lesssim T^\beta$ if either $H\le T^s$ or
		$p\le42/67$.

\label{prop:middle}
		Suppose
		\begin{equation}\label{c:middle-region}
			T^{42/67}\le\rho\le T^{43/67},\qquad H\ge T^s,\qquad M\le T^{1/2}.
		\end{equation}
		Then, uniformly in the shifts, weights, and interval endpoints,
		\begin{equation}\label{c:middle-result}
			|S|/H\lesssim_\varepsilon T^{\beta+\varepsilon}.
		\end{equation}

\label{prop:second}
		Suppose
		\begin{equation}\label{eq:parameter-region}
			\beta\le\tau\le24/67,\qquad \tau+s\le m\le1/2.
		\end{equation}
		Then, uniformly in the shifts, weights, and interval endpoints,
		\begin{equation}\label{eq:larger-result}
			|S|/H\lesssim_\varepsilon T^{\beta+\varepsilon}.
		\end{equation}

\label{lem:pair-reduction}
		For the choice \eqref{c:middle-shift},
		\begin{equation}\label{eq:pair-reduction}
			|S|/H\lesssim_\varepsilon T^\varepsilon
			\left[(T\rho^8(MJ)^6)^{1/30}
			\left(\frac B{HU}\right)^{1/30}
			+\frac{MJ}{\sqrt\rho}+1\right].
		\end{equation}

\label{c:count-prop}
		For the choice \eqref{c:middle-shift},
		\begin{equation}\label{c:count}
			B\lesssim_\varepsilon HU T^\varepsilon.
		\end{equation}

\label{c:middle-proof}
		The preceding two estimates give the conclusion, since
		\begin{equation}\label{c:middle-exponent}
			\begin{gathered}
				T^{36/67}\le MJ\le2T^{36/67},\\
				(T\rho^8(MJ)^6)^{1/30}
				\lesssim T^{(1+8\cdot43/67+6\cdot36/67)/30}=T^{209/670},\\
				\frac{MJ}{\sqrt\rho}\le2T^{15/67}<2T^\beta.
			\end{gathered}
		\end{equation}
		Use smaller positive losses in the two estimates.

\label{lem:farey-Q}
		With these choices,
		\begin{equation}\label{eq:second}
			\frac{|S|}{H}\lesssim_\varepsilon T^\varepsilon
			\left[\frac{M}{\sqrt{HN}}W^{2/9}
			+\frac{M}{N^{3/4}H^{1/4}}W^{1/3}\right].
		\end{equation}

Substituting \eqref{eq:interval-lengths} and \eqref{eq:NR} gives
		\begin{equation}\label{eq:larger-leading}
			\begin{aligned}
				\frac{M}{\sqrt{HN}}W^{2/9}
				&\eqsim T^{1/9}M^{2/3}H^{-5/18}N^{-7/18}\\
				&\lesssim
				\begin{cases}
					T^{(9+\tau)/30},&HM^9\ge T^4,\\
					T^{(2m+1)/6}+T^{(10-7m+4\tau)/27},&HM^9<T^4.
				\end{cases}
			\end{aligned}
		\end{equation}
		The three exponents satisfy
		\[
		\begin{aligned}
			\frac{9+\tau}{30}&\le\frac{9+24/67}{30}=\beta,\\
			10m-\tau<4&\ \Longrightarrow\
			\frac{2m+1}{6}<\frac{9+\tau}{30},\\
			\frac{10-7m+4\tau}{27}
			&\le\frac{10-3\tau-7s}{27}
			\le\frac{10-3\beta-7s}{27}=\beta-\frac1{36180}.
		\end{aligned}
		\]
		Moreover,
		\[
		\frac{M}{N^{3/4}H^{1/4}}W^{1/3}
		=\left(\frac HM\right)^{1/2}
		\left(\frac{M}{\sqrt{HN}}W^{2/9}\right)^{3/2}
		\lesssim T^{(3\beta-\tau)/2}\le T^\beta.
		\]
		Equation~\eqref{eq:second} proves the proposition.

\label{thm:first}
		Under \eqref{eq:first-hyp}, for every $\lambda>0$,
		\begin{equation}\label{eq:mixed}
			\mathcal D(\lambda)\lesssim_\varepsilon(KL)^\varepsilon
			\left((KL)^3\lambda^{-6}+KL^2(L+Z)\lambda^{-4}\right).
		\end{equation}

\label{lem:localization}
		For $\vartheta\in\mathcal P_\Delta$,
		\begin{equation}\label{eq:envelope-counts}
			V^{-1}\|T_\vartheta\|_2^2
			\lesssim_\varepsilon(KL)^\varepsilon\Delta L^2(\Delta+L+Z).
		\end{equation}
		Also,
		\begin{equation}\label{eq:coarse-energy}
			\Delta\ge L+Z\quad\Longrightarrow\quad
			\|T_\vartheta\|_\infty\lesssim\Delta L.
		\end{equation}

\label{lem:finite-separation}
		Let $\Omega$ and $\mathcal I$ be nonempty finite sets, let
		$c_1,c_2:\Omega\to\mathbb R$, and let $J_{I,1},J_{I,2}\subseteq\mathbb R$
		be intervals for $I\in\mathcal I$.
		There are finite families of coefficients $a_{I,j}$ and functions
		$b_j:\Omega\to\mathbb C$ such that, for every $I\in\mathcal I$
		and $\nu\in\Omega$,
		\begin{equation}\label{eq:finite-separation}
			\begin{gathered}
				\mathbf1_{J_{I,1}}(c_1(\nu))\mathbf1_{J_{I,2}}(c_2(\nu))
				=\sum_j a_{I,j}b_j(\nu),\\
				\sum_j\sup_I|a_{I,j}|\sup_\nu|b_j(\nu)|\lesssim\log^2(2+\#\Omega).
			\end{gathered}
		\end{equation}
		For one interval restriction the bound is $O(\log(2+\#\Omega))$.
